  $workspace=Join-Path $operation 'workspace';[IO.Directory]::CreateDirectory($workspace)|Out-Null;Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($zipPath)
  $workerFiles=@('.ci-inputs/worker4.zip','.ci-inputs/worker4-manifest.json','.ci-inputs/worker4-lock.json','.ci-worker/common.ps1','.ci-worker/build.ps1','.ci-worker/offline-only.cjs','.ci-worker/node-job.cs','.gitattributes');$nativeFiles=@('.ci-inputs/native128.zip','.ci-inputs/native128-manifest.json','.ci-inputs/lock.json','.ci-tools/common.ps1','.ci-tools/build-native.ps1','.ci-tools/native-job.cs','.ci-tools/node-job.cs');Require ($privateAsset.packageKind -in @('combined',$Kind)) 'FB_FIXED_PACKAGE_KIND';$expected=if($privateAsset.packageKind -ceq 'combined'){@($workerFiles)+@($nativeFiles)}elseif($Kind -ceq 'worker4'){$workerFiles}else{$nativeFiles}
