  $allowed='^(SystemRoot|WINDIR|COMSPEC|PATH|PATHEXT|USERPROFILE|APPDATA|LOCALAPPDATA|PROGRAMDATA|PUBLIC|HOMEDRIVE|HOMEPATH|NUMBER_OF_PROCESSORS|PROCESSOR_ARCHITECTURE|OS|CARGO_HOME|RUSTUP_HOME|RUSTUP_TOOLCHAIN|INCLUDE|LIB|LIBPATH|VCINSTALLDIR|VSINSTALLDIR|VCToolsInstallDir|VCToolsVersion|WindowsSdkDir|WindowsSDKVersion|WindowsSdkBinPath|WindowsSdkVerBinPath|UniversalCRTSdkDir|UCRTVersion|VSCMD_ARG_HOST_ARCH|VSCMD_ARG_TGT_ARCH|VSCMD_VER|PSModulePath)$';foreach($e in [Environment]::GetEnvironmentVariables().GetEnumerator()){if($e.Key -match $allowed){$psi.Environment[[string]$e.Key]=[string]$e.Value}}
  foreach($name in @('GITHUB_SHA','GITHUB_RUN_ID','GITHUB_RUN_ATTEMPT','GITHUB_REPOSITORY','GITHUB_REF','GITHUB_EVENT_NAME','GITHUB_ACTOR')){$psi.Environment[$name]=[Environment]::GetEnvironmentVariable($name)};$psi.Environment['GITHUB_WORKSPACE']=$workspace;$psi.Environment['RUNNER_TEMP']=$privateTemp;$psi.Environment['TEMP']=$privateTemp;$psi.Environment['TMP']=$privateTemp;$psi.Environment['CI']='true'
